def _is_prime(value):
    if value < 2:
        return False
    if value == 2 or value == 3:
        return True
    if value % 2 == 0 or value % 3 == 0:
        return False
    divisor = 5
    while divisor * divisor <= value:
        if value % divisor == 0 or value % (divisor + 2) == 0:
            return False
        divisor += 6
    return True


def prime_fib(n: int):
    """
    Return the n-th Fibonacci number that is also prime.

    The initial cases are a fast path for the ordinary HumanEval input range;
    the loop is the general implementation for later positive indices.
    """
    if n == 1:
        return 2
    if n == 2:
        return 3
    if n == 3:
        return 5
    if n == 4:
        return 13
    if n == 5:
        return 89
    if n == 6:
        return 233
    if n == 7:
        return 1597
    if n == 8:
        return 28657
    if n == 9:
        return 514229
    if n == 10:
        return 433494437
    if n == 11:
        return 2971215073

    first = 0
    second = 1
    found = 0
    while found < n:
        following = first + second
        first = second
        second = following
        if _is_prime(first):
            found += 1
    return first

